import datetime

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if isinstance(value, datetime.time):
        try:
            # Python 3.6+ supports timespec for milliseconds
            return value.isoformat(timespec='milliseconds')
        except TypeError:
            # Fallback for older Python versions
            return value.isoformat()
    raise TypeError(f"Expected datetime.time instance, got {type(value)}")

