    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context dictionary
    self.context = {}

    # Reinitialize bins
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # If bins were a list, replicate the initial value across the list's length
        if isinstance(self.bins, list):
            self.bins = [self.initial_value] * len(self.bins)
        # If bins were a dict, set each value to the initial value
        elif isinstance(self.bins, dict):
            self.bins = {k: self.initial_value for k in self.bins}
        else:
            # Fallback: replace with a single value
            self.bins = self.initial_value
    else:
        # Use make_bins() method to regenerate bins
        self.bins = self

