            if piece.get("bold"):
                style_attrs.append("font-weight:bold")
            if piece.get("italic"):
                style_attrs.append("font-style:italic")
            if "color" in piece:
                style_attrs.append(f"color:{piece['color']}")
            if style_attrs:
                rendered.append(f"<span style='{ ';'.join(style_attrs)}'>{text}</span>")
            else:
                rendered.append(text)
        else:  # plain text
